beforeExample:
class MyCustomException extends RuntimeException {
    public MyCustomException(String message) { super(message); }
}

public class TestClass {
    public void method() {
        // This statement would trigger a compiler warning about an unused object allocation
        new MyCustomException("An error occurred but was not thrown.");
    }
}

afterExample:
class MyCustomException extends RuntimeException {
    public MyCustomException(String message) { super(message); }
}

public class TestClass {
    public void method() {
        throw new MyCustomException("An error occurred but was not thrown.");
    }
}

negativeExample:
public class TestClass {
    public void method() {
        // This is an unused object, but it is not a Throwable, so this rule should not apply.
        new java.util.ArrayList<String>();

        // This Throwable is used (thrown), so it's not an 'unused allocation' problem.
        throw new java.lang.IllegalArgumentException("Argument invalid");
    }
}
